  Map<String, dynamic> toJson() {
    return {
      'coinName': coinName,
      'datetime': datetime,
      'profitEarned': profitEarned,
      'profitLoss': profitLoss,
    };
  }

  factory Transaction.fromJson(Map<String, dynamic> json) {
    return Transaction(
      json['coinName'],
      json['datetime'],
      json['profitEarned'],
      json['profitLoss'],
    );
  }
}

void main() {
  List<Transaction> transactions = [
    Transaction('BTC', '2022-01-01', 100, 50),
    Transaction('ETH', '2022-01-02', 200, 100),
    Transaction('ETH', '2022-01-03', 150, 75),
    Transaction('BTC', '2022-01-04', 125, 25),
    Transaction('LTC', '2022-01-05', 175, 125),
    Transaction('BTC', '2022-01-06', 150, 50),
    Transaction('ETH', '2022-01-07', 225, 150),
    Transaction('LTC', '2022-01-08', 100, 25),
  ];

  List<Transaction> highestProfitCoins = findTopCoins(transactions, true);
  List<Transaction> highestLossCoins = findTopCoins(transactions, false);

  print('Highest Profit Coins:');
  for (var coin in highestProfitCoins) {
    print('${coin.coinName}: ${coin.profitEarned}');
  }

  print('Highest Loss Coins:');
  for (var coin in highestLossCoins) {
    print('${coin.coinName}: ${coin.profitLoss}');
  }
}

List<Transaction> findTopCoins(List<Transaction> transactions, bool shouldSortProfit) {
  List<Transaction> result = [];
  int count = 0;

  if (shouldSortProfit) {
    transactions.sort((a, b) => b.profitEarned - a.profitEarned);
  } else {
    transactions.sort((a, b) => b.profitLoss - a.profitLoss);
  }

  for (var transaction in transactions) {
    if (result.length < 3) {
      result.add(transaction);
      count++;
    } else {
      double currentAverage = result.map((e) => e.profitEarned).reduce((a, b) => a + b) / result.length;
      double transactionAverage = transaction.profitEarned;

      if (shouldSortProfit) {
        if (transactionAverage > currentAverage) {
          result.removeAt(3);
          result.add(transaction);
          count++;
        }
      } else {
        if (transactionAverage < currentAverage) {
          result.removeAt(3);
          result.add(transaction);
          count++;
        }
      }
    }
  }

  return result;
}
```

