      profitMap[coinName] = [profit];
    } else {
      profitMap[coinName]!.add(profit);
    }

    if (lossMap[coinName] == null) {
      lossMap[coinName] = [loss];
    } else {
      lossMap[coinName]!.add(loss);
    }
  }

  List<CoinMetrics> metrics = [];

  for (String coinName in profitMap.keys) {
    List<double> profits = profitMap[coinName]!;
    List<double> losses = lossMap[coinName]!;
    double avgProfit = profits.reduce(math.add) / profits.length;
    double avgLoss = losses.reduce(math.add) / losses.length;

    metrics.add(CoinMetrics(coinName: coinName, profits: profits, losses: losses, avgProfit: avgProfit, avgLoss: avgLoss));
  }

  return metrics.sortedBy((m) => m.avgProfit).reversed().take(3).toList()..addAll(metrics.sortedBy((m) => m.avgLoss).reversed().take(3));
