given a list of transaction objects that contain coin name,datetime,profit earned/loss. write a function in dart that returns the top three coins with the highest average profit and the top 3 coins with highest average loss. [/Q]
[A]
Here's a Dart function that takes a list of transaction objects and returns the top three coins with the highest average profit and the top three coins with the highest average loss:

```dart
import 'dart:collection';

class Transaction {
  String coinName;
  DateTime datetime;
  double profit;

  Transaction({required this.coinName, required this.datetime, required this.profit});
}

List<String> getTopCoinsWithHighestAverageProfit(List<Transaction> transactions) {
  Map<String, double> coinProfits = {};

  for (Transaction transaction in transactions) {
    String coinName = transaction.coinName;
    double profit = transaction.profit;

    if (coinProfits[coinName] == null) {
      coinProfits[coinName] = profit;
    } else {
      coinProfits[coinName] += profit;
    }
  }

  List<String> topCoins = [];

  for (String coinName in coinProfits.keys) {
    double profit = coinProfits[coinName];
    int rank = topCoins.indexOfWhere((c) => c == coinName, orElse: () => -1);

    if (rank == -1) {
      topCoins.add(coinName);
    } else if (rank < 3) {
      topCoins[rank] = coinName;
    }
  }

  return topCoins;
}

List<String> getTopCoinsWithHighestAverageLoss(List<Transaction> transactions) {
  Map<String, double> coinLosses = {};

  for (Transaction transaction in transactions) {
    String coinName = transaction.coinName;
    double loss = -transaction.profit;

    if (coinLosses[coinName] == null) {
      coinLosses[coinName] = loss;
    } else {
      coinLosses[coinName] += loss;
    }
  }

  List<String> topCoins = [];

  for (String coinName in coinLosses.keys) {
    double loss = coinLosses[coinName];
    int rank = topCoins.indexOfWhere((c) => c == coinName, orElse: () => -1);

    if (rank == -1) {
      topCoins.add(coinName);
    } else if (rank < 3) {
      topCoins[rank] = coinName;
    }
  }

  return topCoins;
}
```

