Here's a Go program that parses a struct in a Go source file and generates a corresponding Avro schema:

```go
package main

import (
	"fmt"
	"io/ioutil"
	"log"
	"regexp"
	"strings"

	"github.com/apache/avro/v2/schema"
)

func main() {
	filePath := "your_go_source_file.go"
	structName := "YourStructName"

	fileContent, err := ioutil.ReadFile(filePath)
	if err != nil {
		log.Fatal(err)
	}

	regex := regexp.MustCompile(`(\w+)\s+(\w+)\s*` +
		`(?::\s*(\w+)\s*)?` +
		`(?::\s*\*\s*)?`)

	fields := make(map[string]string)

	for _, line := range strings.Split(string(fileContent), "\n") {
		match := regex.FindStringSubmatch(line)
		if len(match) == 3 {
			fields[match[1]] = match[2]
		}
	}

	schemaDef := schema.NewSchemaDef()
	schemaDef.Name = structName
	schemaDef.Type = schema.TypeRecord
	schemaDef.Fields = make(map[string]schema.Field)

	for fieldName, fieldType := range fields {
		schemaDef.Fields[fieldName] = schema.Field{
			Name:  fieldName,
			Type:  schema.ParseType(fieldType),
			Doc:   "",
			Default: nil,
		}
	}

	schemaData, err := schemaDef.ToJSON()
	if err != nil {
		log.Fatal(err)
	}

	err = ioutil.WriteFile("struct.avsc", schemaData, 0644)
	if err != nil {
		log.Fatal(err)
	}

	fmt.Printf("Avro schema for %s generated and written to struct.avsc\n", structName)
}
```

